"""Load service configuration."""


DEFAULTS = {'timeout': 30, 'retries': 3}


def load_config(raw):
    return {
        "host": raw["host"],
        "port": raw["port"],
        "timeout": raw.get("timeout", DEFAULTS["timeout"]),
        "retries": raw.get("retries", DEFAULTS["retries"]),
    }
